"""Money arithmetic for invoices."""
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def line_total(qty, unit_price):
    """Round a line to cents, half-up, from the decimal strings it was given."""
    return (Decimal(qty) * Decimal(unit_price)).quantize(CENTS, rounding=ROUND_HALF_UP)


def total(lines):
    """Sum the rounded lines; the invoice total is never re-rounded."""
    return sum(
        (line_total(l["qty"], l["unit_price"]) for l in lines),
        Decimal("0.00"),
    )

